select json_build_object('bucket', (select row_to_json(b) from storage.buckets b where id='drops'), 'objects', (select count(*) from storage.objects where bucket_id='drops'), 'drop', (select json_build_object('script', script, 'audio', audio_url, 'n', jsonb_array_length(picks), 'picks', picks) from public.weekly_drops order by created_at desc limit 1), 'voice', (select json_agg(v) from public.voice_usage v where day = current_date));
